'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
var shape2strides = require( '@stdlib/ndarray/base/shape2strides' );
var dorgbr = require( './../lib' );

// Generate the orthogonal matrix `Q` determined by `dgebrd` when reducing a real `M-by-K` matrix, where `m >= k`:

// Define matrix dimensions:
var M = 4;
var N = 3;
var K = 3;
var shape = [ M, N ];
var order = 'column-major';
var strides = shape2strides( shape, order );

// Create the matrix `A` containing the elementary reflector vectors returned by `dgebrd`:
var A = new Float64Array( [ 1.0, 0.2, -0.1, 0.3, 0.0, 1.0, 0.4, -0.2, 0.0, 0.0, 1.0, 0.5 ] );
console.log( ndarray2array( A, shape, strides, 0, order ) );

// Define the scalar factors and workspace array:
var TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
var WORK = new Float64Array( 10 );

// Generate the orthogonal matrix `Q`:
var info = dorgbr( order, 'Q', M, N, K, A, strides[ 1 ], TAU, WORK, WORK.length );
console.log( ndarray2array( A, shape, strides, 0, order ) );
console.log( info );

// Generate the matrix `P^T` determined by `dgebrd` when reducing a real `K-by-N` matrix, where `k >= n`:

// Define matrix dimensions:
M = 4;
N = 4;
K = 5;
shape = [ M, N ];
strides = shape2strides( shape, order );

// Create the matrix `A` containing the elementary reflector vectors returned by `dgebrd`:
A = new Float64Array( [ 1.0, 0.5, 0.8, 1.1, 0.2, 2.0, 0.9, 1.2, 0.3, 0.6, 3.0, 1.3, 0.4, 0.7, 1.0, 4.0 ] );
console.log( ndarray2array( A, shape, strides, 0, order ) );

// Define the scalar factors and workspace array:
TAU = new Float64Array( [ 1.5, 0.9, 1.3, 0.0 ] );
WORK = new Float64Array( 10 );

// Generate the matrix `P^T`:
info = dorgbr( order, 'P', M, N, K, A, strides[ 1 ], TAU, WORK, WORK.length );
console.log( ndarray2array( A, shape, strides, 0, order ) );
console.log( info );
